import type { InspectionType } from '../stores/flood'
export const titles: Record<InspectionType | 'rescue', string> = { pre: '汛前检查', mid: '汛中巡检', post: '汛后检查', rescue: '求援工单' }
export function cardsFor(kind: InspectionType): CardSpec[] { return kind === 'pre' ? preCards : kind === 'mid' ? midCards : postCards }
export function fieldsFor(kind: InspectionType): FieldSpec[] { return cardsFor(kind).flatMap(card => card.fields) }
export function hasDateField(kind: InspectionType) { return cardsFor(kind).some(card => card.date) }
